void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 res = (iResolution.xy == vec2(0.0)) ? vec2(1024.0) : iResolution.xy;
    vec2 uv = fragCoord / res;

    float d = length(uv - 0.5);
    float ring = 0.5 + 0.5 * sin(40.0 * d - 4.0 * iTime);

    vec3 colA = u_col1;
    vec3 colB = u_col2;
    // Fallback se i colori UI sono entrambi (quasi) bianchi/uguali
    if (length(colA - colB) < 0.05) {
        colA = vec3(0.1, 0.2, 0.8);
        colB = vec3(1.0, 0.6, 0.1);
    }

    fragColor = vec4(mix(colA, colB, ring), 1.0);
}

